/** The desktop's own version, baked in by Vite's `define` from package.json. */
declare const __APP_VERSION__: string;
/** The platform's website, from package.json's `homepage` — the same the Cargo workspace declares. */
declare const __APP_HOMEPAGE__: string;
/** The platform's source repository, from package.json's `repository.url`. */
declare const __APP_REPOSITORY__: string;
